return $input.all().map(i => {
  const name = String(i.json.name || '').trim();
  const isProject = /^TATTOO_\d{4}$/i.test(name);
  const isContainer = !isProject && /^\d{4}$/.test(name);
  return { json: {
    ...i.json,
    molotov_type: isProject ? 'PROJECT' : isContainer ? 'CONTAINER' : 'IGNORE',
    project_id: isProject ? name.toUpperCase() : null,
    project_folder_id: isProject ? i.json.id : null,
    discovered_at: new Date().toISOString()
  }};
});

return $input.all()
  .filter(i => /^TATTOO_\d{4}$/i.test(String(i.json.name || '').trim()))
  .map(i => ({ json: {
    ...i.json,
    molotov_type: 'PROJECT',
    project_id: String(i.json.name).trim().toUpperCase(),
    project_folder_id: i.json.id,
    discovered_at: new Date().toISOString()
  }}));

const discovered = $('NORMALIZE — MEDIA').all().map(i => i.json);
const existing = $input.all().map(i => i.json);

function extractDriveId(url) {
  if (!url) return null;
  for (const r of [/\/file\/d\/([^/]+)/, /[?&]id=([^&]+)/, /\/d\/([^/]+)/]) {
    const m = String(url).match(r);
    if (m?.[1]) return m[1];
  }
  return null;
}

const driveIds = new Set();
const projectNames = new Set();

for (const row of existing) {
  const d = extractDriveId(row.LINK_DRIVE);
  if (d) driveIds.add(d);
  const pid = String(row.ID_PROJETO || '').trim().toUpperCase();
  const fn = String(row.ARQUIVO || '').trim().toLowerCase();
  if (pid && fn) projectNames.add(`${pid}::${fn}`);
}

return discovered.map(a => {
  const scoped = `${String(a.project_id || '').toUpperCase()}::${String(a.file_name || '').trim().toLowerCase()}`;
  const byDrive = Boolean(a.drive_file_id && driveIds.has(a.drive_file_id));
  const byScopedName = Boolean(a.project_id && a.file_name && projectNames.has(scoped));
  const exists = byDrive || byScopedName;
  return { json: {
    ...a,
    already_exists: exists,
    match_method: byDrive ? 'DRIVE_ID' : byScopedName ? 'PROJECT_FILE_NAME' : 'NONE',
    ingestion_action: exists ? 'SKIP' : 'INSERT'
  }};
});

const items = $input.all().map(i => i.json);
const stats = {};
for (const x of items) {
  const p = x.project_id || 'NO_PROJECT';
  stats[p] ??= {total:0, INSERT:0, SKIP:0};
  stats[p].total++;
  stats[p][x.ingestion_action] = (stats[p][x.ingestion_action] || 0) + 1;
}
return items.map(x => ({json:{...x, isolation_audit: stats}}));

// MOLOTOV SOCIAL OS — WRITE PLAN
// Still only calculates rows. Actual writing is armed by the next safety node.

const projectRows = $input.all().map(i => i.json);
const projectContexts = $('CANONICALIZE — PROJECT IDENTITY').all().map(i => i.json);
const media = $('AUDIT — PROJECT ISOLATION').all().map(i => i.json);
const existingMediaRows = $('READ — 03_MIDIAS').all().map(i => i.json);

const now = new Date().toISOString();
const today = now.slice(0, 10);

const existingProjects = new Set(
  projectRows
    .map(r => String(r.ID_PROJETO || '').trim().toUpperCase())
    .filter(Boolean)
);

const uniqueProjects = new Map();
for (const p of projectContexts) {
  const id = String(p.project_id || '').trim().toUpperCase();
  if (!id) continue;
  uniqueProjects.set(id, p);
}

const newProjects = [];
for (const [id, p] of uniqueProjects.entries()) {
  if (existingProjects.has(id)) continue;

  newProjects.push({
    ID_PROJETO: id,
    NOME: id,
    TIPO: 'Tattoo',
    STATUS: 'EM TRIAGEM',
    'SESSÕES': '',
    DATA_INICIAL: '',
    DATA_FINAL: '',
    PASTA_BRUTOS: `https://drive.google.com/drive/folders/${p.project_folder_id}`,
    'ANÁLISE_VISUAL': 'PENDENTE',
    PRIORIDADE: '',
    'OBSERVAÇÕES': 'Cadastro automático de projeto descoberto em 00_BRUTOS.',
    ATUALIZADO_EM: today,

    DRIVE_FOLDER_ID: p.project_folder_id,
    STORAGE_STATUS: 'ONLINE',
    FIRST_SEEN_AT: now,
    LAST_SEEN_AT: now,
    OFFLINE_AT: ''
  });
}

let maxMediaNumber = 0;
for (const r of existingMediaRows) {
  const m = String(r.ID_MIDIA || '').trim().match(/^M(\d+)$/i);
  if (m) maxMediaNumber = Math.max(maxMediaNumber, Number(m[1]));
}

const inserts = media.filter(m => m.ingestion_action === 'INSERT');

const mediaRows = inserts.map((m, index) => {
  const id = `M${String(maxMediaNumber + index + 1).padStart(4, '0')}`;

  return {
    ID_MIDIA: id,
    ID_PROJETO: m.project_id,
    ARQUIVO: m.file_name,
    LINK_DRIVE: `https://drive.google.com/file/d/${m.drive_file_id}/view`,
    TIPO: m.media_type === 'IMAGE' ? 'FOTO' : m.media_type === 'VIDEO' ? 'VÍDEO' : m.media_type,
    DATA_CAPTURA: '',
    'SESSÃO': '',
    TAMANHO: m.file_size_bytes || '',
    TRIAGEM: 'PENDENTE',
    QUALIDADE: '',
    'CONTEÚDO_VISUAL': '',
    MELHOR_TRECHO: '',
    USAR_EM: '',
    'OBSERVAÇÕES': 'Ingestão automática pelo MOLOTOV SOCIAL OS.',

    DRIVE_FILE_ID: m.drive_file_id,
    PROJECT_FOLDER_ID: m.project_folder_id,
    PARENT_FOLDER_ID: m.parent_folder_id || m.project_folder_id,
    RELATIVE_PATH: m.relative_path || m.file_name,
    MIME_TYPE: m.mime_type || '',
    FILE_SIZE_BYTES: m.file_size_bytes || '',
    DRIVE_MODIFIED_AT: m.drive_modified_at || '',
    INGESTION_KEY: m.ingestion_key,
    CONTENT_HASH: '',
    STORAGE_STATUS: 'ONLINE',
    FIRST_SEEN_AT: now,
    LAST_SEEN_AT: now,
    OFFLINE_AT: ''
  };
});

return [{
  json: {
    dry_run: true,
    generated_at: now,
    summary: {
      discovered_projects: uniqueProjects.size,
      existing_projects: existingProjects.size,
      new_projects_to_insert: newProjects.length,
      media_total_discovered: media.length,
      media_existing_skip: media.filter(m => m.ingestion_action === 'SKIP').length,
      media_new_to_insert: mediaRows.length,
      next_media_id_start: mediaRows.length ? mediaRows[0].ID_MIDIA : null,
      next_media_id_end: mediaRows.length ? mediaRows[mediaRows.length - 1].ID_MIDIA : null
    },
    project_rows_to_insert: newProjects,
    media_rows_to_insert: mediaRows
  }
}];

const plan = $input.first().json;

const projects = Array.isArray(plan.project_rows_to_insert)
  ? plan.project_rows_to_insert : [];
const media = Array.isArray(plan.media_rows_to_insert)
  ? plan.media_rows_to_insert : [];

function fail(msg) {
  throw new Error(`WRITE_SAFETY_BLOCK: ${msg}`);
}

if (!plan.dry_run) fail('planner contract invalid');

const mediaIds = media.map(r => String(r.ID_MIDIA || '').trim());
if (new Set(mediaIds).size !== mediaIds.length) fail('duplicate ID_MIDIA in write batch');

const driveIds = media.map(r => String(r.DRIVE_FILE_ID || '').trim()).filter(Boolean);
if (new Set(driveIds).size !== driveIds.length) fail('duplicate DRIVE_FILE_ID in write batch');

for (const p of projects) {
  if (!p.ID_PROJETO || !p.DRIVE_FOLDER_ID || p.STORAGE_STATUS !== 'ONLINE') {
    fail(`invalid project row ${JSON.stringify(p)}`);
  }
}

for (const m of media) {
  if (!m.ID_MIDIA || !m.ID_PROJETO || !m.DRIVE_FILE_ID || !m.INGESTION_KEY) {
    fail(`invalid media row ${JSON.stringify(m)}`);
  }
  if (m.STORAGE_STATUS !== 'ONLINE') fail(`media ${m.ID_MIDIA} is not ONLINE`);
}

return [{
  json: {
    ...plan,
    write_authorized: true,
    write_authorized_at: new Date().toISOString()
  }
}];

// MOLOTOV SOCIAL OS — STORAGE ROTATION PLAN
// Produces exact row updates. The next safety node decides whether writes are allowed.

const now = new Date().toISOString();

const rootItems = $('DISCOVER — 00_BRUTOS').all().map(i => i.json);
const projectContexts = $('CANONICALIZE — PROJECT IDENTITY').all().map(i => i.json);
const discoveredMedia = $('NORMALIZE — MEDIA').all().map(i => i.json);
const projectRows = $('READ — 01_PROJETOS').all().map(i => i.json);
const mediaRows = $('READ — 03_MIDIAS').all().map(i => i.json);

function extractDriveId(url) {
  if (!url) return null;
  const s = String(url);
  for (const p of [
    /\/file\/d\/([^/]+)/,
    /\/folders\/([^/?]+)/,
    /[?&]id=([^&]+)/
  ]) {
    const m = s.match(p);
    if (m?.[1]) return m[1];
  }
  return null;
}

const currentProjects = new Map();
for (const p of projectContexts) {
  const id = String(p.project_id || '').trim().toUpperCase();
  if (!id) continue;
  currentProjects.set(id, p);
}

const currentMediaByDriveId = new Map();
for (const m of discoveredMedia) {
  const d = String(m.drive_file_id || '').trim();
  if (d) currentMediaByDriveId.set(d, m);
}

const projectUpdates = [];
const mediaUpdates = [];
const offlineProjectIds = new Set();

for (const row of projectRows) {
  const pid = String(row.ID_PROJETO || '').trim().toUpperCase();
  if (!pid || !row.row_number) continue;

  const current = currentProjects.get(pid);
  const status = String(row.STORAGE_STATUS || '').trim().toUpperCase();

  if (current) {
    const storedFolderId =
      String(row.DRIVE_FOLDER_ID || '').trim() ||
      extractDriveId(row.PASTA_BRUTOS) ||
      '';

    const needsIdentityBackfill =
      !row.DRIVE_FOLDER_ID ||
      storedFolderId !== String(current.project_folder_id);

    const needsOnlineTransition = status !== 'ONLINE';

    projectUpdates.push({
      row_number: row.row_number,
      ID_PROJETO: pid,
      action:
        needsOnlineTransition
          ? 'SET_ONLINE'
          : needsIdentityBackfill
            ? 'BACKFILL_IDENTITY'
            : 'TOUCH_ONLINE',
      DRIVE_FOLDER_ID: current.project_folder_id,
      STORAGE_STATUS: 'ONLINE',
      FIRST_SEEN_AT: row.FIRST_SEEN_AT || now,
      LAST_SEEN_AT: now,
      OFFLINE_AT: ''
    });
    continue;
  }

  // Only projects previously managed as ONLINE are eligible for automatic OFFLINE.
  if (status === 'ONLINE') {
    offlineProjectIds.add(pid);

    projectUpdates.push({
      row_number: row.row_number,
      ID_PROJETO: pid,
      action: 'SET_OFFLINE',
      DRIVE_FOLDER_ID:
        row.DRIVE_FOLDER_ID ||
        extractDriveId(row.PASTA_BRUTOS) ||
        '',
      STORAGE_STATUS: 'OFFLINE',
      FIRST_SEEN_AT: row.FIRST_SEEN_AT || '',
      LAST_SEEN_AT: row.LAST_SEEN_AT || '',
      OFFLINE_AT: now
    });
  }
}

for (const row of mediaRows) {
  const mid = String(row.ID_MIDIA || '').trim();
  const pid = String(row.ID_PROJETO || '').trim().toUpperCase();
  if (!mid || !pid || !row.row_number) continue;

  const driveId =
    String(row.DRIVE_FILE_ID || '').trim() ||
    extractDriveId(row.LINK_DRIVE) ||
    '';

  const status = String(row.STORAGE_STATUS || '').trim().toUpperCase();

  if (offlineProjectIds.has(pid)) {
    if (status === 'ONLINE') {
      mediaUpdates.push({
        row_number: row.row_number,
        ID_MIDIA: mid,
        ID_PROJETO: pid,
        action: 'SET_OFFLINE',
        DRIVE_FILE_ID: driveId,
        PROJECT_FOLDER_ID: row.PROJECT_FOLDER_ID || '',
        PARENT_FOLDER_ID: row.PARENT_FOLDER_ID || '',
        RELATIVE_PATH: row.RELATIVE_PATH || row.ARQUIVO || '',
        INGESTION_KEY: row.INGESTION_KEY || (driveId ? `gdrive:${driveId}` : ''),
        STORAGE_STATUS: 'OFFLINE',
        FIRST_SEEN_AT: row.FIRST_SEEN_AT || '',
        LAST_SEEN_AT: row.LAST_SEEN_AT || '',
        OFFLINE_AT: now
      });
    }
    continue;
  }

  const current = driveId ? currentMediaByDriveId.get(driveId) : null;

  // Only files physically observed in the active source are refreshed ONLINE.
  if (current) {
    mediaUpdates.push({
      row_number: row.row_number,
      ID_MIDIA: mid,
      ID_PROJETO: pid,
      action: status === 'ONLINE' ? 'TOUCH_ONLINE' : 'SET_ONLINE',
      DRIVE_FILE_ID: driveId,
      PROJECT_FOLDER_ID:
        current.project_folder_id ||
        row.PROJECT_FOLDER_ID ||
        '',
      PARENT_FOLDER_ID:
        current.parent_folder_id ||
        current.project_folder_id ||
        row.PARENT_FOLDER_ID ||
        '',
      RELATIVE_PATH:
        current.relative_path ||
        current.file_name ||
        row.RELATIVE_PATH ||
        row.ARQUIVO ||
        '',
      INGESTION_KEY:
        current.ingestion_key ||
        row.INGESTION_KEY ||
        (driveId ? `gdrive:${driveId}` : ''),
      STORAGE_STATUS: 'ONLINE',
      FIRST_SEEN_AT: row.FIRST_SEEN_AT || now,
      LAST_SEEN_AT: now,
      OFFLINE_AT: ''
    });
  }
}

const summary = {
  root_items_seen: rootItems.length,
  current_projects_seen: currentProjects.size,
  current_media_seen: currentMediaByDriveId.size,
  known_projects: projectRows.filter(r => r.ID_PROJETO).length,
  known_media: mediaRows.filter(r => r.ID_MIDIA).length,

  projects_set_online:
    projectUpdates.filter(x => x.action === 'SET_ONLINE').length,
  projects_set_offline:
    projectUpdates.filter(x => x.action === 'SET_OFFLINE').length,
  projects_identity_backfill:
    projectUpdates.filter(x => x.action === 'BACKFILL_IDENTITY').length,
  projects_touch_online:
    projectUpdates.filter(x => x.action === 'TOUCH_ONLINE').length,

  media_set_online:
    mediaUpdates.filter(x => x.action === 'SET_ONLINE').length,
  media_set_offline:
    mediaUpdates.filter(x => x.action === 'SET_OFFLINE').length,
  media_touch_online:
    mediaUpdates.filter(x => x.action === 'TOUCH_ONLINE').length
};

return [{
  json: {
    generated_at: now,
    summary,
    project_updates: projectUpdates,
    media_updates: mediaUpdates
  }
}];

const plan = $input.first().json;
const summary = plan.summary || {};
const projects = Array.isArray(plan.project_updates) ? plan.project_updates : [];
const media = Array.isArray(plan.media_updates) ? plan.media_updates : [];

function block(msg) {
  throw new Error(`ROTATION_SAFETY_BLOCK: ${msg}`);
}

const validStatus = new Set(['ONLINE', 'OFFLINE']);

for (const p of projects) {
  if (!p.row_number || !p.ID_PROJETO || !validStatus.has(p.STORAGE_STATUS)) {
    block(`invalid project update: ${JSON.stringify(p)}`);
  }
}

for (const m of media) {
  if (!m.row_number || !m.ID_MIDIA || !m.ID_PROJETO || !validStatus.has(m.STORAGE_STATUS)) {
    block(`invalid media update: ${JSON.stringify(m)}`);
  }
}

const projectRows = projects.map(x => Number(x.row_number));
const mediaRows = media.map(x => Number(x.row_number));

if (new Set(projectRows).size !== projectRows.length) {
  block('duplicate project row_number in update batch');
}
if (new Set(mediaRows).size !== mediaRows.length) {
  block('duplicate media row_number in update batch');
}

// Fail closed on a suspicious empty discovery.
// If managed ONLINE projects exist but the source scan sees no project at all,
// we require a manual investigation instead of mass-marking everything OFFLINE.
const knownOnline = $('READ — 01_PROJETOS').all()
  .map(i => i.json)
  .filter(r => String(r.STORAGE_STATUS || '').trim().toUpperCase() === 'ONLINE');

if (knownOnline.length > 0 &&
    Number(summary.current_projects_seen || 0) === 0 &&
    Number(summary.projects_set_offline || 0) > 0) {
  block('zero active projects discovered while ONLINE projects exist');
}

return [{
  json: {
    ...plan,
    rotation_write_authorized: true,
    rotation_write_authorized_at: new Date().toISOString()
  }
}];

// MOLOTOV SOCIAL OS — BUILD SINGLE DRIVE QUERY L0
const projects = $input.all()
  .map(i => i.json)
  .filter(p => p.project_id && p.project_folder_id);

if (projects.length === 0) {
  throw new Error('NO_CANONICAL_PROJECT_CONTEXTS_FOUND');
}

const parentContext = {};
const clauses = [];

for (const p of projects) {
  const folderId = String(p.project_folder_id);

  clauses.push(`'${folderId}' in parents`);

  parentContext[folderId] = {
    project_id: p.project_id,
    project_folder_id: folderId,
    relative_path: '',
    discovered_project_id: p.discovered_project_id || p.project_id,
    project_rename_detected: Boolean(p.project_rename_detected)
  };
}

return [{
  json: {
    tree_query: `(${clauses.join(' or ')}) and trashed = false`,
    parent_context: parentContext,
    folder_count: projects.length,
    depth: 0
  }
}];

// MOLOTOV SOCIAL OS — CLASSIFY TREE L0
const input = $input.all();
const queryContext = $('BUILD — TREE QUERY L0').first().json || {};
const parentContext = queryContext.parent_context || {};

function extension(name) {
  const parts = String(name || '').split('.');
  return parts.length > 1 ? parts.pop().toLowerCase() : '';
}

function mediaType(name) {
  const ext = extension(name);
  if (['jpg','jpeg','png','webp','heic','heif','tif','tiff'].includes(ext)) return 'IMAGE';
  if (['mp4','mov','m4v','avi','mkv','webm'].includes(ext)) return 'VIDEO';
  return 'OTHER';
}

const out = [];

for (const item of input) {
  const f = item.json || {};

  // alwaysOutputData on the Drive node produces one empty item when the query returns 0.
  if (!f.id) {
    continue;
  }

  const parents = Array.isArray(f.parents) ? f.parents : [];
  const parentId = String(parents[0] || '');
  const p = parentContext[parentId];

  if (!p) {
    throw new Error(
      `TREE_PARENT_CONTEXT_NOT_FOUND_L0: file=${f.name || f.id} parent=${parentId || 'MISSING'}`
    );
  }

  const isFolder = f.mimeType === 'application/vnd.google-apps.folder';
  const type = isFolder ? 'OTHER' : mediaType(f.name);
  const supported = type === 'IMAGE' || type === 'VIDEO';

  const basePath = String(p.relative_path || '').trim();
  const relativePath = basePath
    ? `${basePath}/${String(f.name || '')}`
    : String(f.name || '');

  out.push({
    json: {
      tree_type: isFolder ? 'FOLDER' : supported ? 'MEDIA' : 'OTHER',
      depth: 0,

      project_id: p.project_id,
      project_folder_id: p.project_folder_id,
      parent_folder_id: parentId,

      folder_id: isFolder ? f.id : null,

      drive_file_id: isFolder ? null : f.id,
      file_name: String(f.name || ''),
      extension: isFolder ? '' : extension(f.name),
      media_type: type,
      is_supported_media: supported,

      relative_path: relativePath,

      mime_type: f.mimeType || '',
      file_size_bytes: f.size || '',
      drive_modified_at: f.modifiedTime || '',

      source: 'GOOGLE_DRIVE',
      storage_status: supported ? 'ONLINE' : '',
      ingestion_status: supported ? 'DISCOVERED' : '',
      ingestion_key: supported ? `gdrive:${f.id}` : '',

      discovered_at: new Date().toISOString()
    }
  });
}

return out.length ? out : [{ json: { tree_type: 'EMPTY', depth: 0 } }];

// MOLOTOV SOCIAL OS — BUILD SINGLE DRIVE QUERY L1
// All folders found at the previous depth are collapsed into ONE Drive query.
const rows = $input.all().map(i => i.json);
const folders = rows.filter(x => x.tree_type === 'FOLDER' && x.folder_id);

const parentContext = {};
const clauses = [];

for (const f of folders) {
  const folderId = String(f.folder_id);
  clauses.push(`'${folderId}' in parents`);
  parentContext[folderId] = {
    project_id: f.project_id,
    project_folder_id: f.project_folder_id,
    relative_path: f.relative_path || ''
  };
}

if (folders.length === 0) {
  return [{
    json: {
      tree_query: "'10A8m7D4ndeREvZIWKZjiY3eXvb4LDukk' in parents and name = '__MOLOTOV_SENTINEL_NEVER_MATCH__' and trashed = false",
      parent_context: {},
      folder_count: 0,
      depth: 1,
      _sentinel: true
    }
  }];
}

return [{
  json: {
    tree_query: `(${clauses.join(' or ')}) and trashed = false`,
    parent_context: parentContext,
    folder_count: folders.length,
    depth: 1
  }
}];

// MOLOTOV SOCIAL OS — CLASSIFY TREE L1
const input = $input.all();
const queryContext = $('BUILD — TREE QUERY L1').first().json || {};
const parentContext = queryContext.parent_context || {};

function extension(name) {
  const parts = String(name || '').split('.');
  return parts.length > 1 ? parts.pop().toLowerCase() : '';
}

function mediaType(name) {
  const ext = extension(name);
  if (['jpg','jpeg','png','webp','heic','heif','tif','tiff'].includes(ext)) return 'IMAGE';
  if (['mp4','mov','m4v','avi','mkv','webm'].includes(ext)) return 'VIDEO';
  return 'OTHER';
}

const out = [];

for (const item of input) {
  const f = item.json || {};

  // alwaysOutputData on the Drive node produces one empty item when the query returns 0.
  if (!f.id) {
    continue;
  }

  const parents = Array.isArray(f.parents) ? f.parents : [];
  const parentId = String(parents[0] || '');
  const p = parentContext[parentId];

  if (!p) {
    throw new Error(
      `TREE_PARENT_CONTEXT_NOT_FOUND_L1: file=${f.name || f.id} parent=${parentId || 'MISSING'}`
    );
  }

  const isFolder = f.mimeType === 'application/vnd.google-apps.folder';
  const type = isFolder ? 'OTHER' : mediaType(f.name);
  const supported = type === 'IMAGE' || type === 'VIDEO';

  const basePath = String(p.relative_path || '').trim();
  const relativePath = basePath
    ? `${basePath}/${String(f.name || '')}`
    : String(f.name || '');

  out.push({
    json: {
      tree_type: isFolder ? 'FOLDER' : supported ? 'MEDIA' : 'OTHER',
      depth: 1,

      project_id: p.project_id,
      project_folder_id: p.project_folder_id,
      parent_folder_id: parentId,

      folder_id: isFolder ? f.id : null,

      drive_file_id: isFolder ? null : f.id,
      file_name: String(f.name || ''),
      extension: isFolder ? '' : extension(f.name),
      media_type: type,
      is_supported_media: supported,

      relative_path: relativePath,

      mime_type: f.mimeType || '',
      file_size_bytes: f.size || '',
      drive_modified_at: f.modifiedTime || '',

      source: 'GOOGLE_DRIVE',
      storage_status: supported ? 'ONLINE' : '',
      ingestion_status: supported ? 'DISCOVERED' : '',
      ingestion_key: supported ? `gdrive:${f.id}` : '',

      discovered_at: new Date().toISOString()
    }
  });
