// MOLOTOV SOCIAL OS — COLLECT MEDIA FROM ALL TREE LEVELS
const levels = [
  'CLASSIFY — TREE L0',
  'CLASSIFY — TREE L1',
  'CLASSIFY — TREE L2',
  'CLASSIFY — TREE L3',
  'CLASSIFY — TREE L4'
];

const byDriveId = new Map();

for (const nodeName of levels) {
  const items = $(nodeName).all(0, 0);

  for (const item of items) {
    const x = item.json || {};
    if (x.tree_type !== 'MEDIA' || !x.is_supported_media || !x.drive_file_id) continue;

    // Drive file ID is the primary physical identity.
    // If the same file somehow appears twice, keep the shallowest/current occurrence.
    if (!byDriveId.has(x.drive_file_id)) {
      byDriveId.set(x.drive_file_id, x);
    }
  }
}

const media = [...byDriveId.values()].sort((a, b) => {
  const projectCmp = String(a.project_id).localeCompare(String(b.project_id));
  if (projectCmp !== 0) return projectCmp;
  return String(a.relative_path).localeCompare(String(b.relative_path));
});

return media.map((x, index) => ({
  json: {
    ...x,
    discovery_index: index + 1
  }
}));

const media = $('NORMALIZE — MEDIA').all(0, 0).map(i => i.json);

const byProject = {};
const byDepth = {};
const foldersByLevel = {};

for (const m of media) {
  byProject[m.project_id || 'NO_PROJECT'] =
    (byProject[m.project_id || 'NO_PROJECT'] || 0) + 1;

  const d = String(m.depth ?? 'UNKNOWN');
  byDepth[d] = (byDepth[d] || 0) + 1;
}

for (let level = 0; level <= 4; level++) {
  const rows = $(`CLASSIFY — TREE L${level}`).all(0, 0).map(i => i.json);
  foldersByLevel[`L${level}`] =
    rows.filter(x => x.tree_type === 'FOLDER').length;
}

