  json: {
    total_supported_media: media.length,
    by_project: byProject,
    by_depth: byDepth,
    folders_discovered_by_level: foldersByLevel,
    max_supported_depth: 4,
    sample_paths: media.slice(0, 30).map(m => ({
      project_id: m.project_id,
      relative_path: m.relative_path,
      parent_folder_id: m.parent_folder_id,
      depth: m.depth
    }))
  }
}];

// MOLOTOV SOCIAL OS — CANONICAL PROJECT IDENTITY
// Physical Drive folder ID is authoritative.
// Folder name is only the suggested logical ID for brand-new projects.

const discovered = $('PREPARE — PROJECT CONTEXT').all().map(i => i.json);
const existingRows = $input.all().map(i => i.json);

function extractFolderId(url) {
  if (!url) return '';
  const m = String(url).match(/\/folders\/([^/?]+)/);
  return m?.[1] || '';
}

const existingByFolder = new Map();

for (const row of existingRows) {
  const folderId =
    String(row.DRIVE_FOLDER_ID || '').trim() ||
    extractFolderId(row.PASTA_BRUTOS);

  const canonicalId = String(row.ID_PROJETO || '').trim().toUpperCase();

  if (folderId && canonicalId) {
    existingByFolder.set(folderId, {
      canonical_project_id: canonicalId,
      row_number: row.row_number,
      stored_name: row.NOME || '',
      stored_folder_id: folderId
    });
  }
}

return discovered.map(p => {
  const folderId = String(p.project_folder_id || p.id || '').trim();
  const suggestedId = String(p.project_id || p.name || '').trim().toUpperCase();
  const existing = existingByFolder.get(folderId);

  return {
    json: {
      ...p,

      // Preserve the original folder-derived ID for diagnostics only.
      discovered_project_id: suggestedId,

      // Canonical logical identity:
      // existing registry wins when the same physical Drive folder returns.
      project_id: existing?.canonical_project_id || suggestedId,
      project_folder_id: folderId,

      registry_match: existing ? 'DRIVE_FOLDER_ID' : 'NEW_FOLDER',
      project_rename_detected:
        Boolean(existing && existing.canonical_project_id !== suggestedId),

      registry_row_number: existing?.row_number || null,
      canonicalized_at: new Date().toISOString()
    }
  };
});

const projects = $input.all().map(i => i.json);

return [{
  json: {
    projects_seen: projects.length,
    existing_registry_matches:
      projects.filter(p => p.registry_match === 'DRIVE_FOLDER_ID').length,
    brand_new_folders:
      projects.filter(p => p.registry_match === 'NEW_FOLDER').length,
    renames_detected:
      projects.filter(p => p.project_rename_detected).length,
    projects: projects.map(p => ({
      project_id: p.project_id,
      discovered_project_id: p.discovered_project_id,
      project_folder_id: p.project_folder_id,
      registry_match: p.registry_match,
      project_rename_detected: p.project_rename_detected
    }))
